typedef struct {
    float x, y;
} Vector2;

typedef struct {
    Vector2 pos;
    float mass;
} Body;

// Initialization using designated initializers (C99+)
Body particle = {
    .mass = 5.0f,
    .pos = { .x = 10.0f, .y = 20.0f }
};

// Creating temporary aggregates via Compound Literals
void update_body(Body b);
update_body((Body){
    .mass = 1.0f,
    .pos = { .x = 0.0f, .y = 0.0f }
});
